import{_ as o}from"./chunks/fs06-0._-bfDwD6.js";import{_ as a}from"./chunks/fs06-1.BYZknAE2.js";import{_ as e,a as r}from"./chunks/fs11-1.gbHjSq1J.js";import{_ as n,a as l}from"./chunks/fs29-1.DLO3t0-Y.js";import{_ as i,o as s,c as h,a4 as c}from"./chunks/framework.B0hSrcZ6.js";const d="/info/16-knowledge-s1.webp",p="/info/16-knowledge-s2.webp",g="/info/16-knowledge-s4.webp",G=JSON.parse('{"title":"第 16 章 案例：知识自动入库与微信打通","description":"本章介绍将 Grok Bot 与日常通讯工具打通的自动化入库方案。指导读者结合快捷指令与网络钩子归集网页及多模态素材，并在聊天窗口中实现双向交互与云端调度。","frontmatter":{},"headers":[],"relativePath":"part2/16-knowledge.md","filePath":"part2/16-knowledge.md","lastUpdated":1792210948000}'),k={name:"part2/16-knowledge.md"};function b(u,t,f,m,_,q){return s(),h("div",null,[...t[0]||(t[0]=[c('<h1 id="第-16-章-案例-知识自动入库与微信打通" tabindex="-1">第 16 章 案例：知识自动入库与微信打通 <a class="header-anchor" href="#第-16-章-案例-知识自动入库与微信打通" aria-label="Permalink to &quot;第 16 章 案例：知识自动入库与微信打通&quot;">​</a></h1><p>手机收藏容易乱，群文件老过期，人在外头也使不上云端 <strong>7×24 小时</strong> 跑着的 Grok Bot。</p><ol><li>网页与短视频：用 Webhook 配 iOS 快捷指令，<strong>一键结构化入库</strong>。</li><li>截图与录音：微信转发带不出附件，<strong>走公网临时中转</strong>导出来。</li><li>对话调度：用官方「微信ClawBot」插件走长轮询，<strong>在微信窗口直接调度 Grok Bot</strong>。</li></ol><h2 id="三种自动化方案的能力与边界对照" tabindex="-1">三种自动化方案的能力与边界对照 <a class="header-anchor" href="#三种自动化方案的能力与边界对照" aria-label="Permalink to &quot;三种自动化方案的能力与边界对照&quot;">​</a></h2><p><img src="'+d+'" alt="三种自动化方案的能力与边界对照" width="1600" height="1013" decoding="async"></p><table tabindex="0"><thead><tr><th style="text-align:left;">方案与场景</th><th style="text-align:left;">机制与鉴权</th><th style="text-align:left;">坑点</th></tr></thead><tbody><tr><td style="text-align:left;">单向入库（网页、公众号与短视频）</td><td style="text-align:left;">快捷指令带 Bearer 密钥向 Webhook 发 POST 入库</td><td style="text-align:left;">仅单向接收</td></tr><tr><td style="text-align:left;">多模态入库（微信记录、录音、截图多图）</td><td style="text-align:left;">文本直传；文件走 filebin.net 临时网盘生成公网链接，Bot 解压入库</td><td style="text-align:left;"><strong>网盘无密码勿传敏感内容</strong>；大包抽帧多耗 token</td></tr><tr><td style="text-align:left;">微信双向（发指令、查资料、调度 Bot）</td><td style="text-align:left;">微信扫码绑定，iLink 配合云端脚本监听并转 Webhook 回推纯文本</td><td style="text-align:left;"><strong>需控制频次防空转消耗</strong></td></tr></tbody></table><p>自 2026-10-12 起统一为 The X Subscription，均按次扣每周配额。</p><p><strong>$8/月的 Plus 档不含 Grok Bot</strong>，需选 Premium（$30/月或 $300/年，4x 额度）、Super（$100/月或 $1000/年，15x 额度）或 Ultra（$200/月或 $2000/年，50x 额度）。</p><p>细节见官方<a href="https://cursor.com/cn/help/grok-bot/plans" target="_blank" rel="noreferrer">方案和计费</a>。</p><h2 id="案例一-webhook-与快捷指令构建知识自动入库流水线" tabindex="-1">案例一：Webhook 与快捷指令构建知识自动入库流水线 <a class="header-anchor" href="#案例一-webhook-与快捷指令构建知识自动入库流水线" aria-label="Permalink to &quot;案例一：Webhook 与快捷指令构建知识自动入库流水线&quot;">​</a></h2><p><img src="'+p+'" alt="案例一：Webhook 与快捷指令构建知识自动入库流水线" width="1600" height="1013" loading="lazy" decoding="async"></p><p>**方案把抓取、音视频转录与总结全放在 Grok Bot 云端，手机只发 URL 触发。</p><p>** 铁柱AGI（@cgnot996）借<a href="https://cursor.com/cn/help/grok-bot/routines" target="_blank" rel="noreferrer">例程</a>的 Webhook 实现了发请求即刻启动。</p><h3 id="搭建步骤" tabindex="-1">搭建步骤 <a class="header-anchor" href="#搭建步骤" aria-label="Permalink to &quot;搭建步骤&quot;">​</a></h3><ol><li>桌面端 Details 找到 Routines。让 Bot 建立解析任务，<strong>妥善保存生成的 Webhook URL 与 key</strong>。</li><li>新建快捷指令“发送给知识库 Bot”，添加“获取 URL 内容”并按表配置参数。</li></ol><table tabindex="0"><thead><tr><th>参数</th><th>设置值</th></tr></thead><tbody><tr><td>URL</td><td>Webhook 地址</td></tr><tr><td>方法</td><td>POST</td></tr><tr><td>头部</td><td>键名 <code>Authorization</code>，值 <code>Bearer &lt;key&gt;</code></td></tr><tr><td>请求体</td><td>选 JSON，添入“快捷指令输入”</td></tr></tbody></table><ol start="3"><li><strong>针对封闭应用加装辅助输入框</strong>。微信常禁用分享面板，需建第二条指令（“从菜单中选取”加“请求文本”）中转，绑定到 iPhone 操作按钮，按键即可粘贴发送。</li></ol><h3 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/cgnot996/status/2097487429104197688" target="_blank" rel="noreferrer">Grok Bot Webhook + 快捷指令：知识自动入库流水线搭建</a><br> 作者：<a href="https://x.com/cgnot996" target="_blank" rel="noreferrer">铁柱AGI @cgnot996</a></p></blockquote><p><img src="'+o+'" alt="Grok Bot Webhook + 快捷指令：知识自动入库流水线搭建" loading="lazy" decoding="async"></p><p><img src="'+a+'" alt="Grok Bot Webhook + 快捷指令：知识自动入库流水线搭建" loading="lazy" decoding="async"> 点分享后，<strong>几秒内桌面端状态会转为运行中</strong>。任务完成后，知识库会自动生成标准化条目。</p><ul><li>视频 ID 或网页原始短链</li><li>云端存储路径与关联知识页</li><li>核心提炼要点与作者标签</li><li>单次解析消耗的积分成本</li></ul><p>收录《2026 我的 Obsidian 完整分享》等长文时能自动回链。</p><p>实测演示见<a href="https://jcng5q8n0f3z.feishu.cn/wiki/Kxtxw9gLBiqi0nkhZpCc7le5nrh" target="_blank" rel="noreferrer">《Grok Bot Webhook + 快捷指令：知识自动入库流水线搭建》</a>。</p><h2 id="案例二-微信聊天记录与多模态素材打通入库" tabindex="-1">案例二：微信聊天记录与多模态素材打通入库 <a class="header-anchor" href="#案例二-微信聊天记录与多模态素材打通入库" aria-label="Permalink to &quot;案例二：微信聊天记录与多模态素材打通入库&quot;">​</a></h2><h3 id="案例概况" tabindex="-1">案例概况 <a class="header-anchor" href="#案例概况" aria-label="Permalink to &quot;案例概况&quot;">​</a></h3><ul><li>微信合并转发打包传 Grok Bot 自动解压出回执。</li><li><strong>用 filebin.net 作跳板</strong>排除本地路径依赖。</li><li>Mac 与 iPhone 部署 <strong>五种收录模式</strong>快捷指令。</li></ul><h3 id="是什么-为什么需要引入临时网盘中转" tabindex="-1">是什么：为什么需要引入临时网盘中转 <a class="header-anchor" href="#是什么-为什么需要引入临时网盘中转" aria-label="Permalink to &quot;是什么：为什么需要引入临时网盘中转&quot;">​</a></h3><p>跨设备读不到本地盘，微信大 ZIP 塞进请求体容易超时。</p><ol><li>文字直接走 JSON 发送。</li><li>图片、录音和 ZIP 先传 filebin.net，再把链接发给 Bot 下载。</li><li>图床 ID 必须用<strong>至少 8 位随机字母数字</strong>，防止撞名泄露。</li><li>文件默认存 7 天且未加密，<strong>严禁传隐私和商业机密</strong>。</li></ol><h3 id="怎么做-分步搭建步骤" tabindex="-1">怎么做：分步搭建步骤 <a class="header-anchor" href="#怎么做-分步搭建步骤" aria-label="Permalink to &quot;怎么做：分步搭建步骤&quot;">​</a></h3><h4 id="_1-配置-webhook" tabindex="-1">1. 配置 Webhook <a class="header-anchor" href="#_1-配置-webhook" aria-label="Permalink to &quot;1. 配置 Webhook&quot;">​</a></h4><p>在桌面端主会话发这段提示词：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我创建一个 Webhook 触发的例行任务。快捷指令会用 POST 请求发来一个 JSON，里面只有一个字段 info。info 可能是我输入的文字，也可能是一个文件下载链接，比如微信聊天记录压缩包、截图、录音。收到后：如果是链接就先下载文件再读取，压缩包先解压；然后整理出要点，收录进知识库，最后给我一份回执，写清楚收录了什么、存在哪里。</span></span></code></pre></div><p><strong>发送后在 Bot“例程”中记录 Webhook URL 和 key。</strong></p><h4 id="_2-配置快捷指令" tabindex="-1">2. 配置快捷指令 <a class="header-anchor" href="#_2-配置快捷指令" aria-label="Permalink to &quot;2. 配置快捷指令&quot;">​</a></h4><p>导入链接：<code>https://www.icloud.com/shortcuts/2b77155d7c744110a0f0f9ef1bdc42bf</code> 编辑“【分享版】发送给知识库 Bot”，填入 URL、key 与<strong>至少 8 位的复杂图床 ID</strong>（如 kb7x9m2q），标头内置无需修改。</p><h4 id="_3-微信记录收录" tabindex="-1">3. 微信记录收录 <a class="header-anchor" href="#_3-微信记录收录" aria-label="Permalink to &quot;3. 微信记录收录&quot;">​</a></h4><ul><li><strong>Mac 端</strong>：合并转发到其他应用选该指令，点接收转发；ZIP 传网盘推链接，Bot 随即处理。</li><li><strong>手机端</strong>：合并转发选该指令点接收转发；可在“编辑操作”固定到常用区。</li></ul><h4 id="_4-独立调用与采集" tabindex="-1">4. 独立调用与采集 <a class="header-anchor" href="#_4-独立调用与采集" aria-label="Permalink to &quot;4. 独立调用与采集&quot;">​</a></h4><p>Mac 用 Raycast 或菜单栏，手机绑操作按钮。</p><ul><li>截图/录音：确认或录完传网盘推链接。</li><li>输入文字：<strong>直接放进 JSON 发送</strong>，不经网盘。</li><li>选图补充：选图后输说明，打包上传。</li><li>接收转发：未接收内容时读剪贴板发送。</li></ul><h3 id="做到什么程度算好" tabindex="-1">做到什么程度算好 <a class="header-anchor" href="#做到什么程度算好" aria-label="Permalink to &quot;做到什么程度算好&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/cgnot996/status/2107039351519707602" target="_blank" rel="noreferrer">微信聊天记录打通 Grok Bot：快捷指令进阶版</a><br> 作者：<a href="https://x.com/cgnot996" target="_blank" rel="noreferrer">铁柱AGI @cgnot996</a></p></blockquote><p><img src="'+e+'" alt="微信聊天记录打通 Grok Bot：快捷指令进阶版" loading="lazy" decoding="async"></p><p><img src="'+r+'" alt="微信聊天记录打通 Grok Bot：快捷指令进阶版" loading="lazy" decoding="async"></p><p>发送后等几秒到十几秒，Bot 返回<strong>标准化回执</strong>：</p><ul><li><strong>群聊归档</strong>：提取讨论核心论点，给笔记与压缩包路径。</li><li><strong>资源建档</strong>：发 13 个网站，自动分类建索引并给知识库链接。</li></ul><p>操作见<a href="https://jcng5q8n0f3z.feishu.cn/wiki/IwrfwYt1ti0aDWk3YEdcGyQRnUb" target="_blank" rel="noreferrer">《微信聊天记录打通 Grok Bot：快捷指令进阶版》</a>。</p><h2 id="案例三-将-grok-bot-直接接入微信进行双向调度" tabindex="-1">案例三：将 Grok Bot 直接接入微信进行双向调度 <a class="header-anchor" href="#案例三-将-grok-bot-直接接入微信进行双向调度" aria-label="Permalink to &quot;案例三：将 Grok Bot 直接接入微信进行双向调度&quot;">​</a></h2><p><img src="'+g+`" alt="案例三：将 Grok Bot 直接接入微信进行双向调度" width="1600" height="1013" loading="lazy" decoding="async"></p><h3 id="案例概况-1" tabindex="-1">案例概况 <a class="header-anchor" href="#案例概况-1" aria-label="Permalink to &quot;案例概况&quot;">​</a></h3><p>Kin 把 Grok Bot 接进微信，<strong>手机发消息即可遥控云端 Bot</strong>。</p><ol><li>让 Grok 调 iLink 写长轮询脚本</li><li>建 Webhook 接收指令</li><li>微信开「微信ClawBot」扫码绑定</li></ol><p>走纯出站长轮询，<strong>无需开放公网端口</strong>。</p><h3 id="是什么-微信clawbot-与-ilink-长轮询机制" tabindex="-1">是什么：微信ClawBot 与 iLink 长轮询机制 <a class="header-anchor" href="#是什么-微信clawbot-与-ilink-长轮询机制" aria-label="Permalink to &quot;是什么：微信ClawBot 与 iLink 长轮询机制&quot;">​</a></h3><p>方案走官方「微信ClawBot」插件与 iLink 接口（<code>ilinkai.weixin.qq.com</code>），不改客户端内存，<strong>不存在封号风险</strong>。</p><p>通信全是出站请求，<strong>无需开放公网端口</strong>：</p><ol><li>Grok Bot 后台调 <code>getupdates</code> 轮询拉取消息，处理完毕调 <code>sendmessage</code> 回复。</li><li>Webhook 接收文字后交接给各专职 Bot 协同执行，详见文档<a href="https://cursor.com/cn/docs/grok-bot/work" target="_blank" rel="noreferrer">使用 Grok Bot</a>。</li></ol><h3 id="怎么做-手把手操作步骤与完整提示词" tabindex="-1">怎么做：手把手操作步骤与完整提示词 <a class="header-anchor" href="#怎么做-手把手操作步骤与完整提示词" aria-label="Permalink to &quot;怎么做：手把手操作步骤与完整提示词&quot;">​</a></h3><ol><li>电脑端主会话发提示词，等它建好「微信下旨入口」例程。</li></ol><details class="details custom-block"><summary>怎么做：手把手操作步骤与完整提示词</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我想把你接到我的微信上，让我能在微信里直接给你发消息、收到你的回复。请按下面的思路做，每做完一步告诉我结果，需要我操作的地方停下来等我。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1、先调研方案：腾讯「微信ClawBot」插件用的是 iLink 接口（ilinkai.weixin.qq.com）。请确认怎么用 getupdates 长轮询收消息、怎么用 sendmessage 回消息。整个程序只走出站请求，不要开公网端口。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2、在 Grok Bot 里建一个由 webhook 触发的 routine，名字可以叫「微信下旨入口」。建好后告诉我去 routine 面板复制 Webhook URL 和 key，然后弹出加密弹框让我填进去，不要让我在聊天里发明文。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3、在你的云端电脑上写一个小转发程序：收到微信消息后 POST 给这个 routine；你处理完以后，用一个 reply 脚本把回复发回微信，同时在我们的主聊天里同步一份。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4、等我在手机微信里启用 ClawBot 插件以后，生成二维码让我用手机扫码确认，同时给我一个可以在微信里直接打开的备用链接。二维码大约 5 分钟有效。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5、绑定成功后，提醒我先在 ClawBot 对话里发一句话，因为回复要用到这条消息带的 context_token。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>6、规则：只认绑定的这一个人，别人的消息不处理；回复一律用纯文本，不要用 Markdown，因为微信不渲染 Markdown。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>7、最后告诉我：云端电脑重启以后，怎么把转发程序重新拉起来；如果遇到错误码 -14（凭证过期），提醒我重新扫码。</span></span></code></pre></div></details><ol start="2"><li>复制例程的 URL 和 key。<strong>严禁在对话框发明文</strong>，填入机密卡片并显示“已安全保存并保持私密”即可，见<a href="https://cursor.com/cn/help/grok-bot/secrets" target="_blank" rel="noreferrer">安全存储机密信息</a>。</li><li>微信版本需在 <strong>iOS 8.0.70 / Android 8.0.69 以上</strong>。在“我”-&gt;“设置”-&gt;“插件”启用红龙虾图标「微信ClawBot」。</li><li>发送“插件开好了”，微信扫码授权（二维码 <strong>5 分钟有效</strong>，超时用备用链接）。</li><li><strong>必须在微信主动发第一句话</strong>（如“你好”）。接口需藉此截获 <code>context_token</code> 建连，发完通道即正式就绪。</li></ol><h3 id="做到什么程度算好-1" tabindex="-1">做到什么程度算好 <a class="header-anchor" href="#做到什么程度算好-1" aria-label="Permalink to &quot;做到什么程度算好&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/KinGao476942/status/2108132811635032316" target="_blank" rel="noreferrer">如何把 Grok Bot 接入你的微信？保姆级新手指南来了（附详细提示词）</a><br> 作者：<a href="https://x.com/KinGao476942" target="_blank" rel="noreferrer">Kin @KinGao476942</a></p></blockquote><p><img src="`+n+'" alt="如何把 Grok Bot 接入你的微信？保姆级新手指南来了（附详细提示词）" loading="lazy" decoding="async"></p><p><img src="'+l+'" alt="如何把 Grok Bot 接入你的微信？保姆级新手指南来了（附详细提示词）" loading="lazy" decoding="async"></p><p>在微信测这四条，看<strong>有没有跑通</strong>：</p><ol><li>发“你好”，<strong>秒回纯文本</strong>确认。</li><li>调推特专家 Bot，微信直接出选题清单。</li><li>发视频链接调下载专家 Bot，回传清洗文字。</li><li>桌面端同步核对所有指令与记录。</li></ol><p>实操与截图见<a href="https://jcng5q8n0f3z.feishu.cn/wiki/LehUwOhxAijkigkkVlDclVVunQg" target="_blank" rel="noreferrer">《如何把 Grok Bot 接入你的微信？保姆级新手指南来了（附详细提示词）｜Kin》</a>。</p><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><ol><li>转发前<strong>必须在本地点击下载附件</strong>，否则导出的 ZIP 只有占位文本。</li><li>filebin.net 无密码，别用 <code>test</code> 或 <code>123456</code>，<strong>必须设 8 位以上随机字符串</strong>，禁传身份证、银行卡与涉密合同。</li><li>配 Webhook 别在聊天框贴 key，<strong>用安全卡片保存</strong>；共享指令前清空个人 key 和 URL。</li><li>ClawBot 二维码 5 分钟失效，无响应或报 <code>-14</code> 说明<strong>凭证过期，需重新生成扫码</strong>。</li><li>云电脑 Reset 或重启后 Python 轮询会挂，微信没回复就去桌面端<strong>让 Bot 重新拉起脚本</strong>。</li><li>微信不渲染 Markdown，<strong>在 Instruction 强制纯文本回复</strong>，避免输出 <code>**</code> 或 <code>#</code>。</li><li><strong>别同时跑多个 OpenClaw 监听</strong>，防 iLink 队列抢消息漏接指令。</li><li>The X Subscription 扣每周配额，<strong>高频触发必须加过滤</strong>，跑太快就暂停非必要例程或放宽条件。</li></ol><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><ol><li><strong>测 Webhook</strong>：发带 <code>Authorization: Bearer &lt;key&gt;</code> 的 POST 请求。<strong>返回 200 算搞定</strong>，401 是密钥错，404 是 URL 错。电脑端“例程”状态变 Running… 且有日志就行。</li><li><strong>测快捷指令</strong>：发文字测几十秒内出不出回执，转发 2 张图测归档。截图必须弹授权预览，点允许才传。</li><li><strong>测微信与同步</strong>：给「微信ClawBot」发消息，<strong>5 秒内收到回复</strong>算通。再去电脑端看眼，聊天记录同步了就算彻底跑通。</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><h3 id="官方文档" tabindex="-1">官方文档 <a class="header-anchor" href="#官方文档" aria-label="Permalink to &quot;官方文档&quot;">​</a></h3><ul><li><a href="https://cursor.com/cn/help/grok-bot/routines" target="_blank" rel="noreferrer">例程</a></li><li><a href="https://cursor.com/cn/help/grok-bot/secrets" target="_blank" rel="noreferrer">安全存储机密信息</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/work" target="_blank" rel="noreferrer">使用 Grok Bot</a></li><li><a href="https://cursor.com/cn/help/grok-bot/plans" target="_blank" rel="noreferrer">方案和计费</a></li></ul><h3 id="社区实战原文" tabindex="-1">社区实战原文 <a class="header-anchor" href="#社区实战原文" aria-label="Permalink to &quot;社区实战原文&quot;">​</a></h3><ul><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/Kxtxw9gLBiqi0nkhZpCc7le5nrh" target="_blank" rel="noreferrer">《Grok Bot Webhook + 快捷指令：知识自动入库流水线搭建》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/IwrfwYt1ti0aDWk3YEdcGyQRnUb" target="_blank" rel="noreferrer">《微信聊天记录打通 Grok Bot：快捷指令进阶版》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/LehUwOhxAijkigkkVlDclVVunQg" target="_blank" rel="noreferrer">《如何把 Grok Bot 接入你的微信？保姆级新手指南来了（附详细提示词）｜Kin》</a></li></ul>',79)])])}const W=i(k,[["render",b]]);export{G as __pageData,W as default};
